const regions = Tagger.getByTag("st1", {
  sceneId: tile.parent.id
}).filter(doc => doc.documentName === "Region");

for (const region of regions) {
  const disable = region.behaviors.some(b => !b.disabled);

  await region.updateEmbeddedDocuments(
    "RegionBehavior",
    region.behaviors.map(b => ({
      _id: b.id,
      disabled: disable
    }))
  );
}

